<article class="asset-card" data-asset-item data-code="<?php echo e($asset->code); ?>" data-name="<?php echo e($asset->name); ?>" data-type="<?php echo e($asset->type); ?>" data-price="<?php echo e($asset->current_price); ?>" data-variation="<?php echo e($asset->variation_24h); ?>">
    <div class="asset-identity"><span class="asset-token token-<?php echo e(strtolower($asset->code)); ?>"><?php echo e($asset->symbol); ?></span><div><h3><?php echo e($asset->name); ?></h3><span class="asset-meta"><?php echo e($asset->code); ?> <span>·</span> <?php echo e($asset->type === 'crypto' ? 'Criptomoeda' : 'Moeda'); ?></span></div><button class="favorite-button icon-button" type="button" data-favorite="<?php echo e($asset->code); ?>" aria-label="Favoritar <?php echo e($asset->name); ?>" aria-pressed="false" title="Favoritar <?php echo e($asset->name); ?>"><?php echo $__env->make('partials.icon', ['name' => 'star'], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?></button></div>
    <div class="asset-price-block"><span class="small-label">PREÇO EM REAIS</span><strong class="asset-price price"><?php echo e($asset->current_price > 0 ? 'R$ '.number_format((float) $asset->current_price, 4, ',', '.') : 'Aguardando cotação'); ?></strong><?php if($asset->current_price > 0): ?><span class="variation <?php echo e($asset->variation_24h >= 0 ? 'positive' : 'negative'); ?>"><?php echo $__env->make('partials.icon', ['name' => $asset->variation_24h >= 0 ? 'up' : 'down'], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?> <?php echo e($asset->variation_24h > 0 ? '+' : ''); ?><?php echo e(number_format((float) $asset->variation_24h, 2, ',', '.')); ?>% <small>24h</small></span><?php else: ?><span class="variation muted">Sem variação disponível</span><?php endif; ?></div>
    <div class="asset-range"><div><span>Máxima 24h</span><strong class="price"><?php echo e($asset->current_price > 0 ? 'R$ '.number_format((float) $asset->high_price, 4, ',', '.') : '—'); ?></strong></div><div><span>Mínima 24h</span><strong class="price"><?php echo e($asset->current_price > 0 ? 'R$ '.number_format((float) $asset->low_price, 4, ',', '.') : '—'); ?></strong></div></div>
    <div class="asset-actions"><a class="text-action" href="<?php echo e(route('assets.show', $asset)); ?>">Explorar histórico <?php echo $__env->make('partials.icon', ['name' => 'arrow'], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?></a><a class="icon-button" href="<?php echo e(route('alerts.create', ['asset_id' => $asset->id])); ?>" aria-label="Criar alerta para <?php echo e($asset->name); ?>" title="Criar alerta"><?php echo $__env->make('partials.icon', ['name' => 'bell'], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?></a></div>
</article>
